CREATE TABLE IF NOT EXISTS supplier_settlements(
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),job_id UUID NOT NULL UNIQUE REFERENCES service_jobs(id) ON DELETE RESTRICT,quote_id UUID NOT NULL REFERENCES supplier_quotes(id) ON DELETE RESTRICT,supplier_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,payment_transaction_id UUID NOT NULL UNIQUE REFERENCES payment_transactions(id) ON DELETE RESTRICT,gross_amount_minor BIGINT NOT NULL CHECK(gross_amount_minor>0),platform_fee_minor BIGINT NOT NULL CHECK(platform_fee_minor>=0 AND platform_fee_minor<=gross_amount_minor),net_amount_minor BIGINT GENERATED ALWAYS AS (gross_amount_minor-platform_fee_minor) STORED,currency CHAR(3) NOT NULL,status TEXT NOT NULL CHECK(status IN ('PENDING','ELIGIBLE','PROCESSING','PAID','FAILED','HELD')) DEFAULT 'PENDING',payout_reference TEXT UNIQUE,failure_reason TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),paid_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS supplier_settlements_supplier_idx ON supplier_settlements(supplier_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS supplier_settlements_status_idx ON supplier_settlements(status,created_at DESC);
